"use client";

import { useState } from "react";
import { Button } from "../../vip-ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "../../vip-ui/card";
import { Checkbox } from "../../vip-ui/checkbox";
import { Form } from "../../vip-ui/form";
import { Meter } from "../../vip-ui/meter";
import { PasswordField } from "../../vip-ui/password-field";
import { Presence } from "../../vip-ui/presence";
import { Spinner } from "../../vip-ui/spinner";
import { showToast } from "../../vip-ui/toast";

const minLength = 12;

const strengthLabels = ["Too short", "Weak", "Fair", "Good", "Strong"];

function strengthOf(password: string) {
  if (password.length < minLength) return 0;
  let score = 1;
  if (password.length >= 16) score++;
  if (/[a-z]/.test(password) && /[A-Z]/.test(password)) score++;
  if (/\d/.test(password) && /[^A-Za-z0-9]/.test(password)) score++;
  return score;
}

export function PasswordCard({
  otherSessions,
  onSignOutOthers,
}: {
  otherSessions: number;
  onSignOutOthers: () => void;
}) {
  const [current, setCurrent] = useState("");
  const [next, setNext] = useState("");
  const [confirm, setConfirm] = useState("");
  const [signOut, setSignOut] = useState(true);
  const [pending, setPending] = useState(false);
  const [lastChanged, setLastChanged] = useState("Oct 12, 2026");
  const [errors, setErrors] = useState<Record<string, string>>({});
  const strength = strengthOf(next);

  function clearError(field: string) {
    setErrors(({ [field]: _, ...rest }) => rest);
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle as="h2">Password</CardTitle>
        <CardDescription>Last changed {lastChanged}.</CardDescription>
      </CardHeader>
      <Form
        className="contents"
        validationErrors={errors}
        onSubmit={(event) => {
          event.preventDefault();
          const found: Record<string, string> = {};
          if (next.length < minLength)
            found.next = `Use at least ${minLength} characters.`;
          else if (next === current)
            found.next = "Use a password that you do not use now.";
          if (confirm !== next)
            found.confirm = "The two passwords are different.";
          setErrors(found);
          if (Object.keys(found).length > 0) return;
          setPending(true);
          window.setTimeout(() => {
            setPending(false);
            setCurrent("");
            setNext("");
            setConfirm("");
            setLastChanged("Nov 3, 2026");
            if (signOut && otherSessions > 0) onSignOutOthers();
            showToast({
              title: "Password updated",
              description:
                signOut && otherSessions > 0
                  ? "Your other sessions are signed out."
                  : "Your other sessions stay signed in.",
              variant: "success",
            });
          }, 700);
        }}
      >
        <CardContent className="grid max-w-md gap-4">
          <PasswordField
            size="sm"
            name="current"
            label="Current password"
            autoComplete="current-password"
            value={current}
            onChange={setCurrent}
            isRequired
          />
          <div className="grid gap-2">
            <PasswordField
              size="sm"
              name="next"
              label="New password"
              autoComplete="new-password"
              value={next}
              onChange={(value) => {
                setNext(value);
                clearError("next");
              }}
              isRequired
            />
            <Presence show={next.length > 0} collapse>
              <Meter
                label="Strength"
                value={strength}
                maxValue={4}
                valueLabel={strengthLabels[strength]}
                className="pt-1 [&_[data-slot=meter-value]]:font-sans"
              />
            </Presence>
          </div>
          <PasswordField
            size="sm"
            name="confirm"
            label="Confirm new password"
            autoComplete="new-password"
            value={confirm}
            onChange={(value) => {
              setConfirm(value);
              clearError("confirm");
            }}
            isRequired
          />
          <Checkbox checked={signOut} onCheckedChange={setSignOut}>
            Sign out of my other sessions
          </Checkbox>
        </CardContent>
        <CardFooter className="justify-between border-t border-border/70 pt-4">
          <p className="text-xs leading-5 text-muted-foreground">
            Use at least {minLength} characters.
          </p>
          <Button type="submit" size="sm" isDisabled={pending}>
            {pending && <Spinner size="sm" decorative />}
            Update password
          </Button>
        </CardFooter>
      </Form>
    </Card>
  );
}

"use client";

import { useRef, useState } from "react";
import { Alert } from "../../vip-ui/alert";
import { Button } from "../../vip-ui/button";
import {
  Card,
  CardAction,
  CardDescription,
  CardHeader,
  CardTitle,
} from "../../vip-ui/card";
import {
  DialogBody,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "../../vip-ui/dialog";
import { Presence } from "../../vip-ui/presence";
import { TextField } from "../../vip-ui/text-field";
import { showToast } from "../../vip-ui/toast";
import { PasswordCard } from "./password-card";
import { initialSessions, SessionsCard } from "./sessions-card";
import { SettingsShell } from "./settings-shell";
import { TwoStepCard } from "./two-step-card";

const email = "nadia@kestrel.app";

export function SecuritySettings() {
  const [sessions, setSessions] = useState(initialSessions);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [confirmText, setConfirmText] = useState("");
  const [deleted, setDeleted] = useState(false);
  const alertRef = useRef<HTMLDivElement>(null);
  const deleteButtonRef = useRef<HTMLButtonElement>(null);

  return (
    <SettingsShell
      current="security"
      title="Security"
      description="Manage your password, two-step sign-in, and sessions."
    >
      <div className="grid gap-5">
        <Presence show={deleted} collapse>
          <div
            ref={alertRef}
            tabIndex={-1}
            className="outline-none [&>div]:outline-none"
          >
            <Alert
              variant="warning"
              title="Your account closes on Nov 10, 2026"
              action={
                <Button
                  size="sm"
                  variant="outline"
                  onPress={() => {
                    setDeleted(false);
                    showToast({
                      title: "Deletion canceled",
                      description: "Your account stays open.",
                      variant: "success",
                    });
                    requestAnimationFrame(() =>
                      deleteButtonRef.current?.focus(),
                    );
                  }}
                >
                  Keep account
                </Button>
              }
            >
              You can sign in and cancel until that date.
            </Alert>
          </div>
        </Presence>

        <PasswordCard
          otherSessions={sessions.length - 1}
          onSignOutOthers={() =>
            setSessions((current) =>
              current.filter((session) => session.current),
            )
          }
        />
        <TwoStepCard />
        <SessionsCard sessions={sessions} onChange={setSessions} />

        <Card>
          <CardHeader>
            <CardTitle as="h2">Delete account</CardTitle>
            <CardDescription>
              We remove your profile and personal data after 7 days. Kestrel
              Insights stays with its other admins.
            </CardDescription>
            <CardAction>
              <Button
                ref={deleteButtonRef}
                size="sm"
                variant="outline"
                className="border-destructive/40 text-destructive hover:bg-destructive/10 pressed:bg-destructive/10"
                isDisabled={deleted}
                onPress={() => {
                  setConfirmText("");
                  setDeleteOpen(true);
                }}
              >
                Delete account
              </Button>
            </CardAction>
          </CardHeader>
        </Card>
      </div>

      <DialogContent
        role="alertdialog"
        size="sm"
        overlayProps={{
          isOpen: deleteOpen,
          onOpenChange: (open) => {
            if (!open) setDeleteOpen(false);
          },
        }}
      >
        <DialogHeader>
          <DialogTitle level={2}>Delete your account?</DialogTitle>
          <DialogDescription>
            Your account closes on Nov 10, 2026. You cannot undo this after that
            date.
          </DialogDescription>
        </DialogHeader>
        <DialogBody>
          <TextField
            label={`Type ${email} to confirm`}
            value={confirmText}
            onChange={setConfirmText}
            autoComplete="off"
            spellCheck="false"
          />
        </DialogBody>
        <DialogFooter>
          <DialogClose variant="outline">Cancel</DialogClose>
          <Button
            variant="destructive"
            isDisabled={confirmText.trim().toLowerCase() !== email}
            onPress={() => {
              setDeleteOpen(false);
              setDeleted(true);
              showToast({
                title: "Deletion scheduled",
                description: "Your account closes on Nov 10, 2026.",
              });
              window.setTimeout(() => alertRef.current?.focus(), 80);
            }}
          >
            Delete account
          </Button>
        </DialogFooter>
      </DialogContent>
    </SettingsShell>
  );
}

"use client";

import {
  CopyIcon,
  DesktopIcon,
  DeviceMobileIcon,
  DeviceTabletIcon,
  DotsThreeIcon,
  SignOutIcon,
} from "@phosphor-icons/react";
import { useRef } from "react";
import { AnimatedNumber } from "../../vip-ui/animated-number";
import { Badge } from "../../vip-ui/badge";
import { Button } from "../../vip-ui/button";
import {
  Card,
  CardAction,
  CardDescription,
  CardHeader,
  CardTitle,
} from "../../vip-ui/card";
import {
  MenuContent,
  MenuItem,
  MenuPopover,
  MenuSeparator,
  MenuTrigger,
} from "../../vip-ui/menu";
import {
  Cell,
  Column,
  Row,
  Table,
  TableBody,
  TableContainer,
  TableHeader,
} from "../../vip-ui/table";
import { showToast } from "../../vip-ui/toast";

export interface Session {
  id: string;
  device: string;
  browser: string;
  kind: "computer" | "phone" | "tablet";
  location: string;
  ip: string;
  lastActive: string | null;
  current?: boolean;
  isNew?: boolean;
}

export const initialSessions: Session[] = [
  {
    id: "macbook",
    device: "MacBook Pro",
    browser: "Chrome 141 on macOS 15",
    kind: "computer",
    location: "Berlin, Germany",
    ip: "85.214.62.18",
    lastActive: null,
    current: true,
  },
  {
    id: "iphone",
    device: "iPhone 15",
    browser: "Safari on iOS 26",
    kind: "phone",
    location: "Berlin, Germany",
    ip: "85.214.62.40",
    lastActive: "2026-11-03T08:12:00Z",
  },
  {
    id: "dell",
    device: "Dell XPS 15",
    browser: "Edge 142 on Windows 11",
    kind: "computer",
    location: "Lagos, Nigeria",
    ip: "197.210.53.7",
    lastActive: "2026-10-30T21:08:00Z",
    isNew: true,
  },
  {
    id: "ipad",
    device: "iPad Air",
    browser: "Safari on iPadOS 26",
    kind: "tablet",
    location: "Lisbon, Portugal",
    ip: "89.152.18.204",
    lastActive: "2026-09-28T16:20:00Z",
  },
];

const sessionTime = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  hour: "numeric",
  minute: "2-digit",
  timeZone: "UTC",
});

const deviceIcons = {
  computer: DesktopIcon,
  phone: DeviceMobileIcon,
  tablet: DeviceTabletIcon,
};

export function SessionsCard({
  sessions,
  onChange,
}: {
  sessions: Session[];
  onChange: (sessions: Session[]) => void;
}) {
  const headingRef = useRef<HTMLSpanElement>(null);
  const others = sessions.filter((session) => !session.current);

  function signOut(removed: Session[]) {
    const snapshot = sessions;
    onChange(sessions.filter((session) => !removed.includes(session)));
    showToast({
      title:
        removed.length === 1
          ? `${removed[0].device} is signed out`
          : `${removed.length} sessions are signed out`,
      action: { label: "Undo", onAction: () => onChange(snapshot) },
    });
    requestAnimationFrame(() => headingRef.current?.focus());
  }

  async function copyIp(session: Session) {
    try {
      await navigator.clipboard.writeText(session.ip);
      showToast({ title: "IP address copied" });
    } catch {
      showToast({
        title: "Copy failed",
        description: "Select the address in the table.",
        variant: "error",
      });
    }
  }

  return (
    <Card className="overflow-hidden">
      <CardHeader className="pb-4">
        <CardTitle as="h2">
          <span ref={headingRef} tabIndex={-1} className="outline-none">
            Sessions
          </span>
        </CardTitle>
        <CardDescription>
          <AnimatedNumber value={sessions.length} variant="slide" />{" "}
          {sessions.length === 1 ? "device is" : "devices are"} signed in to
          your account.
        </CardDescription>
        <CardAction>
          <Button
            size="sm"
            variant="outline"
            isDisabled={others.length === 0}
            onPress={() => signOut(others)}
          >
            <SignOutIcon aria-hidden="true" />
            Sign out others
          </Button>
        </CardAction>
      </CardHeader>
      <TableContainer className="rounded-none border-x-0 border-b-0 shadow-none">
        <Table aria-label="Sessions" className="min-w-[44rem] [width:100%]!">
          <TableHeader>
            <Column isRowHeader width={280}>
              Device
            </Column>
            <Column width={220}>Location</Column>
            <Column width={150}>Last active</Column>
            <Column width={130}>IP address</Column>
            <Column width={56}>
              <span className="sr-only">Actions</span>
            </Column>
          </TableHeader>
          <TableBody items={sessions}>
            {(session) => {
              const DeviceIcon = deviceIcons[session.kind];
              return (
                <Row id={session.id}>
                  <Cell>
                    <div className="flex items-center gap-3">
                      <span
                        aria-hidden="true"
                        className="grid size-9 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground ring-1 ring-border/60"
                      >
                        <DeviceIcon size={18} />
                      </span>
                      <div className="min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="min-w-0 truncate font-medium">
                            {session.device}
                          </span>
                          {session.current && (
                            <Badge variant="accent">This device</Badge>
                          )}
                        </div>
                        <span className="block truncate text-xs text-muted-foreground">
                          {session.browser}
                        </span>
                      </div>
                    </div>
                  </Cell>
                  <Cell>
                    <div className="flex flex-wrap items-center gap-2">
                      <span>{session.location}</span>
                      {session.isNew && (
                        <Badge variant="warning">New location</Badge>
                      )}
                    </div>
                  </Cell>
                  <Cell className="tabular-nums text-muted-foreground">
                    {session.lastActive ? (
                      <time dateTime={session.lastActive}>
                        {sessionTime.format(new Date(session.lastActive))}
                      </time>
                    ) : (
                      <span className="flex items-center gap-1.5 text-foreground">
                        <span
                          aria-hidden="true"
                          className="size-1.5 rounded-full bg-success"
                        />
                        Active now
                      </span>
                    )}
                  </Cell>
                  <Cell className="font-mono text-xs text-muted-foreground">
                    {session.ip}
                  </Cell>
                  <Cell className="text-end">
                    {!session.current && (
                      <MenuTrigger>
                        <Button
                          variant="ghost"
                          iconOnly
                          size="sm"
                          aria-label={`Actions for ${session.device}`}
                        >
                          <DotsThreeIcon weight="bold" aria-hidden="true" />
                        </Button>
                        <MenuPopover placement="bottom end">
                          <MenuContent
                            aria-label={`Actions for ${session.device}`}
                          >
                            <MenuItem onAction={() => void copyIp(session)}>
                              <CopyIcon size={16} aria-hidden="true" />
                              Copy IP address
                            </MenuItem>
                            <MenuSeparator />
                            <MenuItem
                              variant="destructive"
                              onAction={() => signOut([session])}
                            >
                              <SignOutIcon size={16} aria-hidden="true" />
                              Sign out
                            </MenuItem>
                          </MenuContent>
                        </MenuPopover>
                      </MenuTrigger>
                    )}
                  </Cell>
                </Row>
              );
            }}
          </TableBody>
        </Table>
      </TableContainer>
    </Card>
  );
}

"use client";

import {
  BellIcon,
  CreditCardIcon,
  type Icon,
  KeyIcon,
  PaletteIcon,
  PlugsConnectedIcon,
  ShieldCheckIcon,
  UserCircleIcon,
} from "@phosphor-icons/react";
import { type ReactNode, useEffect, useRef } from "react";
import { Avatar } from "../../vip-ui/avatar";
import { Badge } from "../../vip-ui/badge";
import { ScrollFade } from "../../vip-ui/scroll-fade";
import { cn } from "../../vip-ui/utils";

export type SettingsSection =
  | "profile"
  | "notifications"
  | "security"
  | "appearance"
  | "billing"
  | "api-keys"
  | "integrations";

interface SettingsItem {
  id: SettingsSection;
  label: string;
  href: string;
  icon: Icon;
}

const groups: { title: string; items: SettingsItem[] }[] = [
  {
    title: "Account",
    items: [
      {
        id: "profile",
        label: "Profile",
        href: "/blocks/settings-01",
        icon: UserCircleIcon,
      },
      {
        id: "notifications",
        label: "Notifications",
        href: "/blocks/settings-02",
        icon: BellIcon,
      },
      {
        id: "security",
        label: "Security",
        href: "/blocks/security-01",
        icon: ShieldCheckIcon,
      },
      {
        id: "appearance",
        label: "Appearance",
        href: "/blocks/appearance-01",
        icon: PaletteIcon,
      },
    ],
  },
  {
    title: "Workspace",
    items: [
      {
        id: "billing",
        label: "Billing",
        href: "/blocks/billing-01",
        icon: CreditCardIcon,
      },
      {
        id: "api-keys",
        label: "API keys",
        href: "/blocks/api-keys-01",
        icon: KeyIcon,
      },
      {
        id: "integrations",
        label: "Integrations",
        href: "/blocks/integrations-01",
        icon: PlugsConnectedIcon,
      },
    ],
  },
];

const items = groups.flatMap((group) => group.items);

interface SettingsShellProps {
  current: SettingsSection;
  title: string;
  description: string;
  actions?: ReactNode;
  children: ReactNode;
}

export function SettingsShell({
  current,
  title,
  description,
  actions,
  children,
}: SettingsShellProps) {
  const scroller = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const node = scroller.current;
    const active = node?.querySelector<HTMLElement>("[aria-current=page]");
    if (!node || !active) return;
    node.scrollLeft =
      active.offsetLeft - (node.clientWidth - active.offsetWidth) / 2;
  }, []);

  return (
    <div className="min-h-svh bg-muted/30">
      <header className="sticky top-0 z-30 border-b border-border/70 bg-background/85 backdrop-blur-md">
        <div className="mx-auto flex h-16 w-full max-w-[1280px] items-center gap-3 px-5 sm:px-6 lg:px-8">
          <span
            aria-hidden="true"
            className="grid size-9 shrink-0 place-items-center rounded-xl bg-primary text-base font-bold text-primary-foreground shadow-[var(--shadow-card)]"
          >
            K
          </span>
          <div className="min-w-0">
            <p className="truncate text-sm font-semibold">Kestrel</p>
            <p className="truncate text-xs text-muted-foreground">Settings</p>
          </div>
          <div className="ms-auto flex min-w-0 items-center gap-3">
            <Badge variant="outline" className="max-sm:hidden">
              Pro plan
            </Badge>
            <div className="hidden min-w-0 text-end sm:block">
              <p className="truncate text-sm font-medium leading-5">
                Nadia Okafor
              </p>
              <p className="truncate text-xs leading-4 text-muted-foreground">
                Workspace admin
              </p>
            </div>
            <Avatar name="Nadia Okafor" size="sm" />
          </div>
        </div>
      </header>
      <div className="mx-auto grid w-full max-w-[1280px] gap-6 px-5 py-5 sm:px-6 md:py-8 lg:grid-cols-[14rem_minmax(0,1fr)] lg:items-start lg:gap-10 lg:px-8">
        <aside className="min-w-0 lg:sticky lg:top-[5.5rem]">
          <nav aria-label="Settings">
            <ScrollFade
              ref={scroller}
              orientation="horizontal"
              className="-mx-5 px-5 [scrollbar-width:none] sm:-mx-6 sm:px-6 lg:hidden"
            >
              <ul className="flex w-max gap-1.5 py-1">
                {items.map((item) => (
                  <li key={item.id}>
                    <SettingsLink
                      item={item}
                      active={item.id === current}
                      pill
                    />
                  </li>
                ))}
              </ul>
            </ScrollFade>
            <div className="hidden lg:grid lg:gap-6">
              {groups.map((group) => (
                <div key={group.title} className="min-w-0">
                  <p className="px-3 pb-1.5 text-xs font-medium text-muted-foreground">
                    {group.title}
                  </p>
                  <ul className="grid gap-0.5">
                    {group.items.map((item) => (
                      <li key={item.id}>
                        <SettingsLink
                          item={item}
                          active={item.id === current}
                        />
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </div>
          </nav>
          <div className="mt-7 hidden rounded-xl bg-card p-3.5 shadow-[var(--shadow-card)] ring-1 ring-border/70 lg:block">
            <p className="text-xs font-medium text-muted-foreground">
              Workspace
            </p>
            <p className="mt-2 truncate text-sm font-semibold">
              Kestrel Insights
            </p>
            <p className="truncate text-xs text-muted-foreground">
              12 members · 3 environments
            </p>
          </div>
        </aside>
        <main className="min-w-0">
          <div className="mb-6 flex flex-wrap items-end justify-between gap-x-4 gap-y-3">
            <div className="min-w-0">
              <h1 className="text-2xl font-semibold tracking-[-0.04em]">
                {title}
              </h1>
              <p className="mt-1 max-w-2xl text-sm leading-6 text-muted-foreground">
                {description}
              </p>
            </div>
            {actions}
          </div>
          {children}
        </main>
      </div>
    </div>
  );
}

function SettingsLink({
  item,
  active,
  pill = false,
}: {
  item: SettingsItem;
  active: boolean;
  pill?: boolean;
}) {
  return (
    <a
      href={item.href}
      aria-current={active ? "page" : undefined}
      className={cn(
        "flex min-w-0 items-center gap-2.5 rounded-lg px-3 text-sm font-medium outline-offset-2 outline-transparent transition-[color,background-color] duration-150 ease-out-quint focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-ring",
        pill
          ? "min-h-9 whitespace-nowrap pointer-coarse:min-h-11"
          : "min-h-9 w-full",
        active
          ? "bg-accent text-accent-foreground"
          : "text-muted-foreground hover:bg-muted/70 hover:text-foreground",
      )}
    >
      <item.icon
        size={17}
        weight={active ? "fill" : "regular"}
        aria-hidden="true"
      />
      <span className="truncate">{item.label}</span>
    </a>
  );
}

"use client";

import { DeviceMobileIcon, KeyIcon } from "@phosphor-icons/react";
import { useEffect, useRef, useState } from "react";
import { Alert } from "../../vip-ui/alert";
import { Badge } from "../../vip-ui/badge";
import { Button } from "../../vip-ui/button";
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "../../vip-ui/card";
import { CopyButton } from "../../vip-ui/copy-button";
import {
  DialogBody,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "../../vip-ui/dialog";
import { Form } from "../../vip-ui/form";
import { InlineCode } from "../../vip-ui/kbd-code";
import { LayoutMorph } from "../../vip-ui/layout-morph";
import { Presence } from "../../vip-ui/presence";
import { Switch } from "../../vip-ui/switch";
import { TextField } from "../../vip-ui/text-field";
import { TextSwap } from "../../vip-ui/text-swap";
import { showToast } from "../../vip-ui/toast";

const authenticatorKey = "JBSW Y3DP EHPK 3PXP";

const initialRecoveryCodes = [
  "7Q4M-2K9P",
  "B8XR-5T1N",
  "F2WD-8J6C",
  "L9YA-3H7S",
  "P4NE-6V2R",
  "T6CU-9M3B",
  "X7GA-1D8K",
  "Z3HF-5W9L",
];

function newRecoveryCodes() {
  const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  return Array.from({ length: 8 }, () =>
    Array.from({ length: 8 }, () =>
      alphabet.charAt(Math.floor(Math.random() * alphabet.length)),
    ).join(""),
  ).map((code) => `${code.slice(0, 4)}-${code.slice(4)}`);
}

function MethodIcon({ children }: { children: React.ReactNode }) {
  return (
    <span
      aria-hidden="true"
      className="grid size-9 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground ring-1 ring-border/70"
    >
      {children}
    </span>
  );
}

function RecoveryCodes({ codes }: { codes: string[] }) {
  return (
    <ul className="grid grid-cols-2 gap-x-4 gap-y-2 rounded-lg bg-muted/60 p-4 font-mono text-sm tracking-wide ring-1 ring-border/70">
      {codes.map((code) => (
        <li key={code}>{code}</li>
      ))}
    </ul>
  );
}

export function TwoStepCard() {
  const [enabled, setEnabled] = useState(false);
  const [alerts, setAlerts] = useState(true);
  const [setupOpen, setSetupOpen] = useState(false);
  const [step, setStep] = useState(1);
  const [code, setCode] = useState("");
  const [codeError, setCodeError] = useState("");
  const [recoveryCodes, setRecoveryCodes] = useState(initialRecoveryCodes);
  const [codesOpen, setCodesOpen] = useState(false);
  const [disableOpen, setDisableOpen] = useState(false);
  const copyCodesRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!(setupOpen && step === 2)) return;
    const frame = requestAnimationFrame(() => copyCodesRef.current?.focus());
    return () => cancelAnimationFrame(frame);
  }, [setupOpen, step]);

  function openSetup() {
    setStep(1);
    setCode("");
    setCodeError("");
    setSetupOpen(true);
  }

  function verifyCode() {
    if (code.length !== 6) {
      setCodeError("Enter the 6-digit code from your app.");
      return;
    }
    if (code === "000000") {
      setCodeError("That code is not correct. Wait for the next code.");
      return;
    }
    setCodeError("");
    setStep(2);
  }

  function finishSetup() {
    setEnabled(true);
    setSetupOpen(false);
    showToast({
      title: "Two-step sign-in is on",
      description: "We ask for a code each time you sign in.",
      variant: "success",
    });
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle as="h2">Two-step sign-in</CardTitle>
        <CardDescription>
          Add a second step to keep your account safe.
        </CardDescription>
        <CardAction>
          <Badge variant={enabled ? "success" : "neutral"} dot={enabled}>
            {enabled ? "On" : "Off"}
          </Badge>
        </CardAction>
      </CardHeader>
      <CardContent className="grid gap-4">
        <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-3">
          <div className="flex min-w-0 items-center gap-3">
            <MethodIcon>
              <DeviceMobileIcon size={18} />
            </MethodIcon>
            <div className="min-w-0">
              <p className="text-sm font-medium">Authenticator app</p>
              <p className="text-xs leading-5 text-muted-foreground">
                <TextSwap
                  value={
                    enabled
                      ? "Added Nov 3, 2026"
                      : "Use a 6-digit code from an app on your phone."
                  }
                />
              </p>
            </div>
          </div>
          <Button
            size="sm"
            variant={enabled ? "outline" : "default"}
            onPress={enabled ? () => setDisableOpen(true) : openSetup}
          >
            {enabled ? "Turn off" : "Set up"}
          </Button>
        </div>
        <Presence show={enabled} collapse>
          <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-3 border-t border-border/70 pt-4">
            <div className="flex min-w-0 items-center gap-3">
              <MethodIcon>
                <KeyIcon size={18} />
              </MethodIcon>
              <div className="min-w-0">
                <p className="text-sm font-medium">Recovery codes</p>
                <p className="text-xs leading-5 text-muted-foreground">
                  {recoveryCodes.length} codes left. Each code works one time.
                </p>
              </div>
            </div>
            <Button
              size="sm"
              variant="outline"
              onPress={() => setCodesOpen(true)}
            >
              View codes
            </Button>
          </div>
        </Presence>
        <div className="border-t border-border/70 pt-4">
          <Switch
            checked={alerts}
            onCheckedChange={setAlerts}
            description="We send an email when a new device signs in."
            className="w-full"
          >
            Sign-in alerts
          </Switch>
        </div>
      </CardContent>

      <DialogContent
        size="md"
        overlayProps={{
          isOpen: setupOpen,
          onOpenChange: (open) => {
            if (!open) setSetupOpen(false);
          },
        }}
      >
        <Form
          className="contents"
          validationErrors={codeError ? { code: codeError } : undefined}
          onSubmit={(event) => {
            event.preventDefault();
            verifyCode();
          }}
        >
          <DialogHeader>
            <DialogTitle level={2}>
              <TextSwap
                value={
                  step === 1
                    ? "Set up two-step sign-in"
                    : "Save your recovery codes"
                }
              />
            </DialogTitle>
            <DialogDescription>
              {step === 1
                ? "Step 1 of 2. Add this key to your authenticator app."
                : "Step 2 of 2. Use a code if you lose your phone."}
            </DialogDescription>
            <DialogClose />
          </DialogHeader>
          <DialogBody>
            <LayoutMorph contentKey={step}>
              {step === 1 ? (
                <div className="grid gap-4">
                  <div className="rounded-lg bg-muted/60 p-4 ring-1 ring-border/70">
                    <p className="text-sm font-medium">Setup key</p>
                    <div className="mt-2 flex min-w-0 items-center gap-2">
                      <InlineCode className="min-w-0 flex-1 px-2.5 py-1.5 text-sm tracking-[0.14em]">
                        {authenticatorKey}
                      </InlineCode>
                      <CopyButton
                        value={authenticatorKey}
                        iconOnly
                        size="sm"
                        variant="ghost"
                        aria-label="Copy setup key"
                      />
                    </div>
                  </div>
                  <TextField
                    name="code"
                    label="6-digit code"
                    value={code}
                    onChange={(value) => {
                      setCode(value.replace(/\D/g, "").slice(0, 6));
                      setCodeError("");
                    }}
                    inputMode="numeric"
                    autoComplete="one-time-code"
                    placeholder="123456"
                    description="The code changes every 30 seconds."
                    autoFocus
                  />
                </div>
              ) : (
                <div className="grid gap-4">
                  <Alert variant="warning" title="Store these codes now">
                    We do not show them again after you close this window.
                  </Alert>
                  <RecoveryCodes codes={recoveryCodes} />
                </div>
              )}
            </LayoutMorph>
          </DialogBody>
          {step === 1 ? (
            <DialogFooter>
              <DialogClose variant="outline">Cancel</DialogClose>
              <Button type="submit">Verify code</Button>
            </DialogFooter>
          ) : (
            <DialogFooter>
              <CopyButton
                ref={copyCodesRef}
                value={recoveryCodes.join("\n")}
                variant="outline"
              >
                Copy codes
              </CopyButton>
              <Button onPress={finishSetup}>Finish setup</Button>
            </DialogFooter>
          )}
        </Form>
      </DialogContent>

      <DialogContent
        size="md"
        overlayProps={{
          isOpen: codesOpen,
          onOpenChange: (open) => {
            if (!open) setCodesOpen(false);
          },
        }}
      >
        <DialogHeader>
          <DialogTitle level={2}>Recovery codes</DialogTitle>
          <DialogDescription>
            Use a code to sign in when you do not have your phone.
          </DialogDescription>
          <DialogClose />
        </DialogHeader>
        <DialogBody>
          <RecoveryCodes codes={recoveryCodes} />
        </DialogBody>
        <DialogFooter>
          <Button
            variant="ghost"
            className="sm:me-auto"
            onPress={() => {
              setRecoveryCodes(newRecoveryCodes());
              showToast({
                title: "New recovery codes are ready",
                description: "The old codes no longer work.",
              });
            }}
          >
            Make new codes
          </Button>
          <CopyButton value={recoveryCodes.join("\n")} variant="outline">
            Copy codes
          </CopyButton>
          <DialogClose variant="default">Done</DialogClose>
        </DialogFooter>
      </DialogContent>

      <DialogContent
        role="alertdialog"
        size="sm"
        overlayProps={{
          isOpen: disableOpen,
          onOpenChange: (open) => {
            if (!open) setDisableOpen(false);
          },
        }}
      >
        <DialogHeader>
          <DialogTitle level={2}>Turn off two-step sign-in?</DialogTitle>
          <DialogDescription>
            Your password becomes the only sign-in step. Your recovery codes
            stop working.
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <DialogClose variant="outline">Cancel</DialogClose>
          <Button
            variant="destructive"
            onPress={() => {
              setEnabled(false);
              setDisableOpen(false);
              setRecoveryCodes(initialRecoveryCodes);
              showToast({ title: "Two-step sign-in is off" });
            }}
          >
            Turn off
          </Button>
        </DialogFooter>
      </DialogContent>
    </Card>
  );
}
